"""One isolated ingestion probe; generated bytes only, no provider or private corpus."""

from __future__ import annotations

import argparse
import json
import resource
import time
from io import BytesIO
from zipfile import ZIP_STORED, ZipFile

from idml_foundation.ingest.safe_zip import UnsafeArchiveError, inspect_idml
from idml_foundation.pipeline.idml_parser import IdmlParser
from idml_foundation.settings import Settings

CASES = {
    "nodes_100k": 100_000,
    "nodes_500k": 500_000,
    "nodes_2m": 2_000_000,
    "xml_oversize": 0,
    "mimetype_oversize": 0,
    "expanded_oversize": 0,
    "xml_total_near_limit": 0,
    "xml_total_over_limit": 0,
}


def payload(case):
    out = BytesIO()
    with ZipFile(out, "w", compression=ZIP_STORED) as archive:
        archive.writestr(
            "mimetype",
            b"x" * 4096
            if case == "mimetype_oversize"
            else b"application/vnd.adobe.indesign-idml-package",
        )
        archive.writestr("designmap.xml", b"<Document/>")
        if CASES[case]:
            archive.writestr("Resources/Unused.xml", b"<Root>" + b"<n/>" * CASES[case] + b"</Root>")
        elif case == "xml_oversize":
            with archive.open("Resources/Unused.xml", "w") as entry:
                for _ in range(512):
                    entry.write(b"x" * 65536)
                entry.write(b"x")
        elif case == "expanded_oversize":
            archive.writestr("Resources/Unused.xml", b"<Root/>" * 1024)
        elif case in {"xml_total_near_limit", "xml_total_over_limit"}:
            size = 1024**2 - (1 if case == "xml_total_near_limit" else 0)
            for index in range(16):
                archive.writestr(
                    f"Resources/Unused{index}.xml", b"<Root>" + b"x" * (size - 13) + b"</Root>"
                )
    return out.getvalue()


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--case", choices=CASES, required=True)
    args = parser.parse_args()
    started = time.perf_counter()
    settings = Settings(environment="test")
    if args.case == "expanded_oversize":
        settings.zip_max_uncompressed_bytes = 1024
    data = payload(args.case)
    status = "accepted"
    try:
        if args.case.startswith("nodes_") or args.case == "xml_total_near_limit":
            IdmlParser(settings).parse(data, logical_name="synthetic.idml")
        else:
            inspect_idml(data, settings)
    except UnsafeArchiveError as exc:
        status = "rejected:" + exc.code
    print(
        json.dumps(
            {
                "case": args.case,
                "status": status,
                "input_bytes": len(data),
                "peak_rss_bytes": resource.getrusage(resource.RUSAGE_SELF).ru_maxrss * 1024,
                "elapsed_seconds": round(time.perf_counter() - started, 3),
                "restricted_content_emitted": False,
            }
        ),
        flush=True,
    )


if __name__ == "__main__":
    main()
